function dealTwoPiles(nums: number[]): number[] {
  const left = [nums[0]], right = [nums[1]];
  for (let i = 2; i < nums.length; i++) {
    if (left[left.length - 1] > right[right.length - 1]) left.push(nums[i]);
    else right.push(nums[i]);
  }
  return left.concat(right);
}

