    def dealTwoPiles(self, nums: List[int]) -> List[int]:
        left, right = [nums[0]], [nums[1]]
        for x in nums[2:]:
            if left[-1] > right[-1]:
                left.append(x)
            else:
                right.append(x)
        return left + right

