function dealTwoPiles(nums: number[]): number[] {
  const side: boolean[] = [true, false]; // true = left pile
  let topL = nums[0], topR = nums[1];
  for (let i = 2; i < nums.length; i++) {
    if (topL > topR) { side.push(true); topL = nums[i]; }
    else { side.push(false); topR = nums[i]; }
  }
  return [...nums.filter((_, i) => side[i]), ...nums.filter((_, i) => !side[i])];
}

