class Solution:
    def dealTwoPiles(self, nums: List[int]) -> List[int]:
        side = [True, False]  # True = left pile
        top_l, top_r = nums[0], nums[1]
        for x in nums[2:]:
            if top_l > top_r:
                side.append(True)
                top_l = x
            else:
                side.append(False)
                top_r = x
        return [x for x, s in zip(nums, side) if s] + [x for x, s in zip(nums, side) if not s]

